import multiprocessing as mp, os, time
d = float(os.environ["DURATION_S"])
end = time.time() + d if d > 0 else float("inf")
def burn():
    while time.time() < end:
        pass
ps = [mp.Process(target=burn) for _ in range(int(os.environ["CORES"]))]
[p.start() for p in ps]
[p.join() for p in ps]

